 const balMap = typeof computeRunningBalances === 'function' ? computeRunningBalances() : null;
 document.getElementById("recentTxnList").innerHTML = list.map(e=>txnRowHTML(e, false, balMap ? balMap.get(String(e.id)) : null)).join("");
