function saveToDeletedHistory(entry) {
 const history = JSON.parse(localStorage.getItem('deletedEntries') || '[]');
 history.unshift({
  ...entry,
  deletedAt: new Date().toISOString()
 });
 localStorage.setItem('deletedEntries', JSON.stringify(history));
}

